import{_ as r,l as n,o as e,c as l,v as i,p as s,x as o,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"双折射与偏振像差","description":"","frontmatter":{"title":"双折射与偏振像差","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/birefringence-polarization.md","filePath":"litho/birefringence-polarization.md","lastUpdated":1789023840000}'),c={name:"litho/birefringence-polarization.md"};function _(m,a,A,E,f,u){const t=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=i('<h1 id="双折射与偏振像差" tabindex="-1">双折射与偏振像差 <a class="header-anchor" href="#双折射与偏振像差" aria-label="Permalink to &quot;双折射与偏振像差&quot;">​</a></h1><div class="epigraph"><p>应力双折射把一块玻璃变成弱波片。高 NA 下 s/p 已经分家，再叠材料波片，Jones 瞳就不再是标量相位。</p><footer>—— 对照 [Jones 矩阵](/litho/jones-polarization)、[矢量成像](/litho/vector-imaging)；CaF₂ 应力双折射</footer></div><p><a href="/litho/lens-aberration-metrology">上一课</a>量标量波前。缺口是偏振：材料与镀膜的二向色性、应力双折射、末片的 s/p 菲涅尔。主干 Jones 课已有符号；本课落到物镜硬件。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Zernike 相位假定两种偏振看见同一 \\(W\\)。高 NA 浸没下，对照明偏振敏感的层（<a href="/litho/illuminator-polarization">照明偏振</a>）会把材料波片放大成 NILS 损失或套刻的偏振依赖。只补标量操纵器，CD 仍随偏振态变。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选低应力双折射牌号、退火、安装应力控制。计量：偏振波前（Jones 瞳）或至少双偏振 Zernike。照明侧用偏振控制匹配物镜特征，而不是「越偏振越好」。</p>',7)),(e(),s(h,null,{default:o(()=>[p(t,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20STR%5B%22%E5%AE%89%E8%A3%85%20%2F%20%E7%83%AD%E5%BA%94%E5%8A%9B%22%5D%20--%3E%20BR%5B%22%E5%8F%8C%E6%8A%98%E5%B0%84%22%5D%0A%20%20BR%20--%3E%20J%5B%22Jones%20%E7%9E%B3%22%5D%0A%20%20NA%5B%22%E9%AB%98%20NA%20%E8%8F%B2%E6%B6%85%E5%B0%94%22%5D%20--%3E%20J%0A%20%20J%20--%3E%20NILS%5B%22%E5%AF%B9%E6%AF%94%20%2F%20%E5%A5%97%E5%88%BB%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p><span class="marginnote">CaF₂ 比熔石英更易因应力露双折射。上一课的材料分配现在有偏振代价，不是只有透过率。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>应力光弹性系数把 \\(\\sigma\\) 变成 \\(\\Delta n\\)。快轴沿应力主方向，等效在光瞳上贴位置相关的延迟片，混合 s/p。矢量成像核因此含偏振像差，TCC 标量化失效。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课污染：薄膜脏了也会改相位和散射，但是颗粒与碳氢，不是体双折射。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>物镜像差有偏振通道；标量 Zernike 不够高 NA。</li><li>材料应力与末片菲涅尔一起进 Jones 瞳。</li><li>出处：Jones / 矢量成像课；CaF₂ 应力双折射通识。</li></ul>',7))])}const T=r(c,[["render",_]]);export{b as __pageData,T as default};
